{"command":"cd /tmp/clearai060-native-comparison/workspaces/additive-C/.clearai-reruns/6fcbeb2bb2d23169f622e45f9a481b64096ee4b0ba8b19e65b0e17d11bd53ad8 && python3 - <<'EOF'
import json, numpy as np
def des(p, inter=True):
    p=np.asarray(p,float); x=p[:,0]; y=p[:,1]
    c=[np.ones(len(x)),x,y,x*x,y*y]
    if inter: c.append(x*y)
    return np.column_stack(c)
def scaled(p):
    p=np.asarray(p,float); return 2*p-1
for name,path in [('9pt','initial.json'),('16pt','lab/input-final.json')]:
    rows=json.load(open(path))['observations']
    P=scaled(np.array([[r['x'],r['y']] for r in rows])); V=np.array([r['value'] for r in rows])
    A=des(P,True); co=np.linalg.lstsq(A,V,rcond=None)[0]; res=V-A@co
    s2=float(res@res/(len(V)-6)); cov=s2*np.linalg.pinv(A.T@A)
    se=np.sqrt(np.diag(cov))
    print(name,'n',len(V),'inter coef',round(co[5],4),'se',round(se[5],4),'t',round(co[5]/se[5],2),'95%CI',(round(co[5]-1.96*se[5],3),round(co[5]+1.96*se[5],3)),'resid sd',round(np.sqrt(s2),4))
    # physical xy coeff = 4*coef
    print('   physical xy coef',round(4*co[5],3),'CI',(round(4*(co[5]-1.96*se[5]),3),round(4*(co[5]+1.96*se[5]),3)))
EOF","description":"Interaction coefficient standard errors"}

